function h($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function postv($k,$d=''){ return $_POST[$k] ?? $d; }
function admin_datetime_or_null($raw,$fallback=''){
  $raw=trim((string)$raw); if($raw==='') $raw=trim((string)$fallback); if($raw==='') return null;
  $raw=str_replace('T',' ',$raw); if(preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/',$raw)) $raw.=':00';
  $ts=strtotime($raw); return $ts ? date('Y-m-d H:i:s',$ts) : null;
}
function admin_datetime_local_value($raw){ $raw=trim((string)$raw); if($raw==='') return ''; $ts=strtotime(str_replace('T',' ',$raw)); return $ts ? date('Y-m-d\TH:i',$ts) : ''; }
function money($v){ return '₹'.number_format((float)$v,2); }
function qcount(mysqli $c,string $sql): int { $r=@$c->query($sql); return $r?(int)($r->fetch_assoc()['c']??0):0; }
function qsum(mysqli $c,string $sql): float { $r=@$c->query($sql); return $r?(float)($r->fetch_assoc()['s']??0):0; }
function audit_log(mysqli $conn,string $action,string $target='',string $detail=''){
  @ $conn->query("CREATE TABLE IF NOT EXISTS admin_audit_log(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, admin_user VARCHAR(120), action VARCHAR(120), target VARCHAR(190), detail TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $admin=$_SESSION['admin_user']??'admin'; $st=@$conn->prepare('INSERT INTO admin_audit_log(admin_user,action,target,detail,created_at) VALUES(?,?,?,?,NOW())'); if($st){$st->bind_param('ssss',$admin,$action,$target,$detail);$st->execute();}
}
