<div class="card"><h3>Licenses</h3><div class="scroll"><table><tr><th>Key</th><th>Customer / Domain</th><th>Status</th><th>Valid until / Quick Save</th><th>Block/Edit/Delete</th><th>Popup to client</th></tr><?php $rs=$lc->query('SELECT * FROM owner_licenses ORDER BY id DESC LIMIT 300'); while($r=$rs->fetch_assoc()):?><tr><td><b><?=h($r['license_key'])?></b><br><span class="help"><?=h($r['note'])?></span></td><td><?=h($r['customer_name'])?><br><?=h($r['domain'])?></td><td><span class="pill <?=($r['status']==='blocked'||$r['status']==='expired')?'badge-red':'badge-green'?>"><?=h($r['status'])?></span></td><td><form method="post" class="row"><input type="hidden" name="action" value="owner_license_validity"><input type="hidden" name="id" value="<?=h($r['id'])?>"><input class="mini" type="datetime-local" name="valid_until" value="<?=h(admin_datetime_local_value($r['valid_until']??''))?>"><select name="status"><option <?=($r['status']==='active')?'selected':''?>>active</option><option <?=($r['status']==='blocked')?'selected':''?>>blocked</option><option <?=($r['status']==='expired')?'selected':''?>>expired</option><option <?=($r['status']==='inactive')?'selected':''?>>inactive</option></select><button>Save Validity</button></form><span class="help"><?=h($r['valid_until'])?></span></td><td><form method="post" class="row"><input type="hidden" name="action" value="owner_license_status"><input type="hidden" name="id" value="<?=h($r['id'])?>"><select name="status"><option>active</option><option>blocked</option><option>expired</option><option>inactive</option></select><button>Update</button></form><form method="post" class="row" onsubmit="return confirm('Delete license?')"><input type="hidden" name="action" value="owner_license_delete"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="bad">Delete</button></form></td><td><form method="post"><input type="hidden" name="action" value="owner_license_popup"><input type="hidden" name="id" value="<?=h($r['id'])?>"><textarea name="popup_message" placeholder="Popup message"><?=h($r['popup_message']??'')?></textarea><div class="row"><input class="mini" name="popup_duration" value="<?=h($r['popup_duration']??60)?>" placeholder="sec"><input class="mini" name="popup_minutes" value="1" placeholder="minutes"><input name="owner_telegram" value="<?=h($r['owner_telegram']??'')?>" placeholder="telegram"><button>Push Popup</button></div></form></td></tr><?php endwhile;?></table></div></div>
<div class="card"><h3>Domain Whitelist</h3><div class="scroll"><table><tr><th>Domain</th><th>License Key</th><th>Name</th><th>Status</th><th>Valid until</th><th>Auto days</th><th>Message</th></tr><?php $wrs=$lc->query('SELECT * FROM owner_domain_whitelist ORDER BY id DESC LIMIT 300'); while($w=$wrs->fetch_assoc()):?><tr><td><b><?=h($w['domain'])?></b></td><td><?=h($w['license_key'])?></td><td><?=h($w['customer_name'])?></td><td><span class="pill <?=((int)$w['status'])?'badge-green':'badge-red'?>"><?=((int)$w['status'])?'active':'off'?></span></td><td><?=h($w['valid_until']??'')?></td><td><?=h($w['auto_days']??30)?></td><td><?=h($w['message']??'')?></td></tr><?php endwhile;?></table></div></div>
<div class="grid2"><div class="card"><h3>Global Message / Payment</h3><form method="post"><input type="hidden" name="action" value="owner_global_message"><label>Message<textarea name="popup_message"><?=h($lm['popup_message']??'')?></textarea></label><div class="grid3"><label>Telegram<input name="telegram_url" value="<?=h($lm['telegram_url']??'') ?>"></label><label>UPI ID<input name="upi_id" value="<?=h($lm['upi_id']??'') ?>"></label><label>UPI Name<input name="upi_name" value="<?=h($lm['upi_name']??'') ?>"></label><label>QR path<input name="qr_image" value="<?=h($lm['qr_image']??'') ?>"></label></div><button>Save Message</button></form></div><div class="card"><h3>Client Chat / Renewal</h3><div class="scroll"><table><tr><th>Domain</th><th>Contact</th><th>Question</th><th>Reply</th></tr><?php $rs=$lc->query('SELECT * FROM owner_license_chat ORDER BY id DESC LIMIT 100'); while($c=$rs->fetch_assoc()):?><tr><td><?=h($c['domain'])?><br><?=h($c['license_key'])?></td><td><?=h($c['name'])?><br><?=h($c['contact'])?></td><td><?=h($c['message'])?><br><b><?=h($c['reply'])?></b></td><td><form method="post" class="row"><input type="hidden" name="action" value="owner_chat_reply"><input type="hidden" name="id" value="<?=h($c['id'])?>"><input name="reply" placeholder="reply"><button>Send</button></form></td></tr><?php endwhile;?></table></div></div></div>
<?php endif;?>

<?php if($tab==='admins'): $tabs=['dashboard'=>'Dashboard','users'=>'Users','deposits'=>'Deposit Orders','withdraw'=>'Withdraw','payment'=>'Payment/UPI','recharge_history'=>'Recharge History','finance'=>'Finance Report','workorders'=>'User Queries','bonus'=>'Bonus/Gift','tasks'=>'Tasks','wheel'=>'Invite Wheel','agents'=>'Agents','lottery'=>'Lottery','results'=>'Result History','settings'=>'Settings','owner_license'=>'Owner License','admins'=>'Admins'];?><div class="grid2"><div class="card"><h3>Add Admin + Permissions</h3><form method="post"><input type="hidden" name="action" value="admin_create"><label>Username<input name="username" placeholder="new admin username"></label><label>Password<input name="password" value="admin123"></label><div class="row"><?php foreach($tabs as $k=>$v):?><label class="toggle"><input type="checkbox" name="perms[]" value="<?=h($k)?>" checked><span class="switch"></span><?=h($v)?></label><?php endforeach;?></div><button>Create Admin</button></form></div><div class="card"><h3>Permission Tips</h3><p style="color:#8ea3bf">Admin ko sirf selected modules ka access do. Main admin username <b>admin</b> ko full access rahega.</p></div></div><div class="card"><h3>Admins</h3><?php $rs=$conn->query("SELECT u.id,u.username,u.status,u.created_at,p.permissions,p.status perm_status FROM users u LEFT JOIN admin_permissions p ON p.admin_user=u.username WHERE u.role='admin' ORDER BY u.id DESC");?><div class="scroll"><table><tr><th>ID</th><th>User</th><th>Status</th><th>Permissions</th><th>Save</th></tr><?php while($a=$rs->fetch_assoc()): $ap=json_decode((string)($a['permissions']??'[]'),true); if(!is_array($ap))$ap=[];?><tr><form method="post"><td>#<?=h($a['id'])?></td><td><?=h($a['username'])?><input type="hidden" name="admin_user" value="<?=h($a['username'])?>"></td><td><label class="toggle"><input type="checkbox" name="status" <?=((int)($a['perm_status']??1))?'checked':''?>><span class="switch"></span>Active</label></td><td><div class="row"><?php foreach($tabs as $k=>$v):?><label class="toggle"><input type="checkbox" name="perms[]" value="<?=h($k)?>" <?=(in_array('*',$ap,true)||in_array($k,$ap,true)||$a['username']==='admin')?'checked':''?>><span class="switch"></span><?=h($v)?></label><?php endforeach;?></div></td><td><input type="hidden" name="action" value="admin_perm_save"><button>Save</button></td></form></tr><?php endwhile;?></table></div></div><?php endif;?>
